create extension if not exists pgcrypto;

create type public.user_role as enum ('ADMIN', 'CLIENT');
create type public.content_scope as enum ('GLOBAL', 'CLIENT');
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path = public as $$ begin new.updated_at = now(); return new; end; $$;

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, role public.user_role not null default 'CLIENT', full_name text, avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.plans (id uuid primary key default gen_random_uuid(), name text not null, description text, price_cents integer not null default 0 check (price_cents >= 0), currency text not null default 'BRL', is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.clients (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references auth.users(id) on delete cascade, plan_id uuid references public.plans(id) on delete set null, status text not null default 'active', last_access_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.subscriptions (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, plan_id uuid references public.plans(id) on delete set null, status text not null default 'trialing', started_at timestamptz, expires_at timestamptz, provider text, provider_subscription_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.payments (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, subscription_id uuid references public.subscriptions(id) on delete set null, amount_cents integer not null check (amount_cents >= 0), status text not null default 'pending', provider text, provider_payment_id text, paid_at timestamptz, created_at timestamptz not null default now());
create table public.exercise_categories (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, created_at timestamptz not null default now());
create table public.exercises (id uuid primary key default gen_random_uuid(), category_id uuid references public.exercise_categories(id) on delete set null, name text not null, description text, instructions text, thumbnail_url text, muscles text[] not null default '{}', equipment text, level text, scope public.content_scope not null default 'GLOBAL', client_id uuid references public.clients(id) on delete cascade, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint exercises_scope_owner check (scope = 'GLOBAL' or client_id is not null));
create table public.videos (id uuid primary key default gen_random_uuid(), provider text not null default 'youtube', provider_video_id text not null, title text not null, thumbnail_url text, duration_seconds integer, type text, category_id uuid references public.exercise_categories(id) on delete set null, scope public.content_scope not null default 'GLOBAL', client_id uuid references public.clients(id) on delete cascade, description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint videos_scope_owner check (scope = 'GLOBAL' or client_id is not null));
create table public.media_assets (id uuid primary key default gen_random_uuid(), bucket text not null, path text not null, alt_text text, scope public.content_scope not null default 'GLOBAL', client_id uuid references public.clients(id) on delete cascade, created_at timestamptz not null default now(), constraint media_scope_owner check (scope = 'GLOBAL' or client_id is not null));
create table public.workouts (id uuid primary key default gen_random_uuid(), name text not null, description text, category text, level text, duration_minutes integer, cover_asset_id uuid references public.media_assets(id) on delete set null, status text not null default 'draft', scope public.content_scope not null default 'GLOBAL', client_id uuid references public.clients(id) on delete cascade, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint workouts_scope_owner check (scope = 'GLOBAL' or client_id is not null));
create table public.workout_exercises (id uuid primary key default gen_random_uuid(), workout_id uuid not null references public.workouts(id) on delete cascade, exercise_id uuid not null references public.exercises(id) on delete restrict, video_id uuid references public.videos(id) on delete set null, position integer not null default 0, sets integer, repetitions text, load text, rest_seconds integer, notes text, unique (workout_id, position));
create table public.progress_weights (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, value numeric(6,2) not null check (value > 0), recorded_at date not null, created_at timestamptz not null default now());
create table public.progress_measurements (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, measurements jsonb not null default '{}', recorded_at date not null, created_at timestamptz not null default now());
create table public.progress_photos (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, asset_id uuid references public.media_assets(id) on delete set null, category text, recorded_at date not null, created_at timestamptz not null default now());
create table public.performance_records (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, metric text not null, value numeric, unit text, recorded_at date not null, created_at timestamptz not null default now());
create table public.nutrition_plans (id uuid primary key default gen_random_uuid(), name text not null, description text, scope public.content_scope not null default 'GLOBAL', client_id uuid references public.clients(id) on delete cascade, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint nutrition_scope_owner check (scope = 'GLOBAL' or client_id is not null));
create table public.recipes (id uuid primary key default gen_random_uuid(), name text not null, description text, ingredients jsonb not null default '[]', instructions text, scope public.content_scope not null default 'GLOBAL', client_id uuid references public.clients(id) on delete cascade, created_at timestamptz not null default now(), constraint recipes_scope_owner check (scope = 'GLOBAL' or client_id is not null));
create table public.shopping_lists (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, name text not null, items jsonb not null default '[]', created_at timestamptz not null default now());
create table public.tip_categories (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, created_at timestamptz not null default now());
create table public.tips (id uuid primary key default gen_random_uuid(), category_id uuid references public.tip_categories(id) on delete set null, title text not null, content text not null, scope public.content_scope not null default 'GLOBAL', client_id uuid references public.clients(id) on delete cascade, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint tips_scope_owner check (scope = 'GLOBAL' or client_id is not null));
create table public.massage_services (id uuid primary key default gen_random_uuid(), name text not null, description text, duration_minutes integer, is_active boolean not null default true, created_at timestamptz not null default now());
create table public.massage_sessions (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, service_id uuid references public.massage_services(id) on delete set null, scheduled_at timestamptz, duration_minutes integer, professional text, status text not null default 'scheduled', notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), client_id uuid references public.clients(id) on delete cascade, title text not null, body text not null, read_at timestamptz, created_at timestamptz not null default now());
create table public.achievements (id uuid primary key default gen_random_uuid(), name text not null, description text, icon_url text, created_at timestamptz not null default now());
create table public.user_achievements (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, achievement_id uuid not null references public.achievements(id) on delete cascade, achieved_at timestamptz not null default now(), unique(client_id, achievement_id));
create table public.support_messages (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, sender_id uuid not null references auth.users(id) on delete cascade, message text not null, status text not null default 'open', created_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), admin_id uuid not null references auth.users(id) on delete restrict, action text not null, entity text not null, entity_id uuid, old_value jsonb, new_value jsonb, created_at timestamptz not null default now());
create table public.app_settings (key text primary key, value jsonb not null default '{}', updated_at timestamptz not null default now());

create index clients_user_id_idx on public.clients(user_id);
create index scoped_content_client_idx on public.exercises(client_id);
create index scoped_videos_client_idx on public.videos(client_id);
create index scoped_workouts_client_idx on public.workouts(client_id);
create index client_history_weights_idx on public.progress_weights(client_id, recorded_at);
create index client_history_measurements_idx on public.progress_measurements(client_id, recorded_at);
create index client_history_photos_idx on public.progress_photos(client_id, recorded_at);

create or replace function public.handle_new_user() returns trigger language plpgsql security invoker set search_path = public as $$ begin insert into public.profiles (id, full_name) values (new.id, coalesce(new.raw_user_meta_data ->> 'full_name', '')); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create trigger profiles_updated_at before update on public.profiles for each row execute procedure public.set_updated_at();
create trigger clients_updated_at before update on public.clients for each row execute procedure public.set_updated_at();
create trigger plans_updated_at before update on public.plans for each row execute procedure public.set_updated_at();
create trigger subscriptions_updated_at before update on public.subscriptions for each row execute procedure public.set_updated_at();
create trigger exercises_updated_at before update on public.exercises for each row execute procedure public.set_updated_at();
create trigger videos_updated_at before update on public.videos for each row execute procedure public.set_updated_at();
create trigger workouts_updated_at before update on public.workouts for each row execute procedure public.set_updated_at();
create trigger nutrition_plans_updated_at before update on public.nutrition_plans for each row execute procedure public.set_updated_at();
create trigger tips_updated_at before update on public.tips for each row execute procedure public.set_updated_at();
create trigger massage_sessions_updated_at before update on public.massage_sessions for each row execute procedure public.set_updated_at();

do $$ declare t text; begin foreach t in array array['profiles','clients','plans','subscriptions','payments','exercise_categories','exercises','videos','media_assets','workouts','workout_exercises','progress_weights','progress_measurements','progress_photos','performance_records','nutrition_plans','recipes','shopping_lists','tip_categories','tips','massage_services','massage_sessions','notifications','achievements','user_achievements','support_messages','audit_logs','app_settings'] loop execute format('alter table public.%I enable row level security', t); end loop; end $$;
create policy "profiles own read" on public.profiles for select to authenticated using ((select auth.uid()) = id);
create policy "profiles own update" on public.profiles for update to authenticated using ((select auth.uid()) = id) with check ((select auth.uid()) = id);
create policy "clients own read" on public.clients for select to authenticated using ((select auth.uid()) = user_id);
create policy "clients own update" on public.clients for update to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy "admin profiles read" on public.profiles for select to authenticated using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'ADMIN');
create policy "admin clients access" on public.clients for all to authenticated using ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'ADMIN') with check ((select auth.jwt() -> 'app_metadata' ->> 'role') = 'ADMIN');
do $$ declare t text; begin foreach t in array array['plans','subscriptions','payments','exercise_categories','exercises','videos','media_assets','workouts','workout_exercises','progress_weights','progress_measurements','progress_photos','performance_records','nutrition_plans','recipes','shopping_lists','tip_categories','tips','massage_services','massage_sessions','notifications','achievements','user_achievements','support_messages','audit_logs','app_settings'] loop execute format('create policy "admin full access %1$s" on public.%1$I for all to authenticated using ((select auth.jwt() -> ''app_metadata'' ->> ''role'') = ''ADMIN'') with check ((select auth.jwt() -> ''app_metadata'' ->> ''role'') = ''ADMIN'')', t); end loop; end $$;
create policy "global exercise read" on public.exercises for select to authenticated using (scope = 'GLOBAL' or client_id in (select id from public.clients where user_id = (select auth.uid())));
create policy "global video read" on public.videos for select to authenticated using (scope = 'GLOBAL' or client_id in (select id from public.clients where user_id = (select auth.uid())));
create policy "global workout read" on public.workouts for select to authenticated using (scope = 'GLOBAL' or client_id in (select id from public.clients where user_id = (select auth.uid())));
create policy "global nutrition read" on public.nutrition_plans for select to authenticated using (scope = 'GLOBAL' or client_id in (select id from public.clients where user_id = (select auth.uid())));
create policy "global recipe read" on public.recipes for select to authenticated using (scope = 'GLOBAL' or client_id in (select id from public.clients where user_id = (select auth.uid())));
create policy "global tip read" on public.tips for select to authenticated using (scope = 'GLOBAL' or client_id in (select id from public.clients where user_id = (select auth.uid())));
create policy "own subscriptions read" on public.subscriptions for select to authenticated using (client_id in (select id from public.clients where user_id = (select auth.uid())));
create policy "own payments read" on public.payments for select to authenticated using (client_id in (select id from public.clients where user_id = (select auth.uid())));
create policy "own progress read" on public.progress_weights for select to authenticated using (client_id in (select id from public.clients where user_id = (select auth.uid())));
create policy "own measurements read" on public.progress_measurements for select to authenticated using (client_id in (select id from public.clients where user_id = (select auth.uid())));
create policy "own photos read" on public.progress_photos for select to authenticated using (client_id in (select id from public.clients where user_id = (select auth.uid())));
create policy "own massage read" on public.massage_sessions for select to authenticated using (client_id in (select id from public.clients where user_id = (select auth.uid())));
create policy "own notifications read" on public.notifications for select to authenticated using (client_id in (select id from public.clients where user_id = (select auth.uid())));
create policy "own achievements read" on public.user_achievements for select to authenticated using (client_id in (select id from public.clients where user_id = (select auth.uid())));
create policy "own messages read" on public.support_messages for select to authenticated using (client_id in (select id from public.clients where user_id = (select auth.uid())) or sender_id = (select auth.uid()));
create policy "active plans read" on public.plans for select to authenticated using (is_active = true);
create policy "exercise categories read" on public.exercise_categories for select to authenticated using (true);
create policy "tip categories read" on public.tip_categories for select to authenticated using (true);
create policy "active massage services read" on public.massage_services for select to authenticated using (is_active = true);

insert into storage.buckets (id, name, public) values ('images', 'images', false) on conflict (id) do nothing;
create policy "authenticated image read" on storage.objects for select to authenticated using (bucket_id = 'images' and ((storage.foldername(name))[1] = 'global' or ((storage.foldername(name))[1] in ('clients', 'progress') and ((storage.foldername(name))[2])::uuid in (select id from public.clients where user_id = (select auth.uid()))) or (select auth.jwt() -> 'app_metadata' ->> 'role') = 'ADMIN');
create policy "admin image write" on storage.objects for all to authenticated using (bucket_id = 'images' and (select auth.jwt() -> 'app_metadata' ->> 'role') = 'ADMIN') with check (bucket_id = 'images' and (select auth.jwt() -> 'app_metadata' ->> 'role') = 'ADMIN');
insert into public.plans (name, description, price_cents) values ('Básico', 'Plano inicial', 2990), ('Personalizado', 'Plano acompanhado', 5990), ('Premium', 'Plano completo', 8990);
